const ACCOUNT_HANDLE_PATTERN = /^@[A-Za-z0-9._-]+$/;

const decodeAccountHandle = (value: string) => {
  try {
    return decodeURIComponent(value.trim());
  } catch {
    return '';
  }
};

export const normalizeAccountHandle = (value: string): string | null => {
  const decoded = decodeAccountHandle(value);
  if (!decoded) return null;

  const accountHandle = decoded.startsWith('@') ? decoded : `@${decoded}`;
  return ACCOUNT_HANDLE_PATTERN.test(accountHandle) ? accountHandle : null;
};

export const accountUsernameFromHandle = (value: string): string | null => {
  if (!decodeAccountHandle(value).startsWith('@')) return null;
  const accountHandle = normalizeAccountHandle(value);
  return accountHandle ? accountHandle.slice(1) : null;
};

export const buildAccountPath = (accountHandle: string, nestedPath = '') => {
  const normalizedHandle = normalizeAccountHandle(accountHandle);
  if (!normalizedHandle) {
    throw new Error('Invalid account handle.');
  }

  const suffix = nestedPath
    ? nestedPath.startsWith('/')
      ? nestedPath
      : `/${nestedPath}`
    : '';

  if (suffix.startsWith('//') || suffix.includes('\\')) {
    throw new Error('Invalid account path.');
  }

  const encodedHandle = encodeURIComponent(normalizedHandle).replace(/^%40/i, '@');
  return `/${encodedHandle}${suffix}`;
};

export const buildWorkspacePath = (
  accountHandle: string,
  pageName = 'overview',
  restPath?: string,
) => {
  const segments = [
    'workspace',
    pageName,
    ...(restPath?.split('/').filter(Boolean) ?? []),
  ].map((segment) => encodeURIComponent(segment));

  return buildAccountPath(accountHandle, `/${segments.join('/')}`);
};
